const LazyLoadImages=function(){const t=[".nav-logo",".loader-logo","#hero-image",'[fetchpriority="high"]',".hero-section img:first-child","[data-no-lazy]"];function o(){document.querySelectorAll("img:not([loading])").forEach(o=>{(function(o){for(const n of t)try{if(o.matches(n)||o.closest(n))return!0}catch(t){}const n=o.getBoundingClientRect();return n.top<600&&n.top>=0})(o)||(o.loading="lazy",o.decoding="async")})}return{init:function(){"loading"===document.readyState?document.addEventListener("DOMContentLoaded",function(){setTimeout(o,100)}):setTimeout(o,100)}}}();LazyLoadImages.init();